sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

    var ga = new GlideAjax("GlideAjax");
    ga.addParam("sysparm_name", "blockDuplicateTrainings");
    ga.addParam("sysparm_course", g_form.getValue("course"));
    ga.addParam("sysparm_training_date", g_form.getValue("training_date"));

    ga.getXMLAnswer(function(response) {
        if(response == "true"){
            g_form.addErrorMessage("duplicate training");
            g_form.setValue("training_date", "");
        } else{
            g_form.clearMessages();
        }
    });

}
